Here is the commit message:
netfs: Fix a NULL vs IS_ERR() check in netfs_perform_write()

The netfs_grab_folio_for_write() function doesn't return NULL, it returns
error pointers.  Update the check accordingly.

Fixes: c38f4e96e605 ("netfs: Provide func to copy data to pagecache for buffered write")
Signed-off-by: Dan Carpenter <dan.carpenter@linaro.org>
Signed-off-by: David Howells <dhowells@redhat.com>
Link: https://lore.kernel.org/r/29fb1310-8e2d-47ba-b68d-40354eb7b896@moroto.mountain/

Here is the root cause:
The bug arises from an incorrect assumption in the error handling logic of the `netfs_perform_write()` function. The function `netfs_grab_folio_for_write()` was expected to return `NULL` on failure, but it actually returns error pointers. This discrepancy led to improper error checking, which could result in unhandled error conditions and potential crashes or undefined behavior.

Here is the patch:
  */
 ssize_t netfs_perform_write(struct kiocb *iocb, struct iov_iter *iter,
 			    struct netfs_group *netfs_group)
 {
 	struct file *file = iocb->ki_filp;
 	struct inode *inode = file_inode(file);
 	struct address_space *mapping = inode->i_mapping;
 	struct netfs_inode *ctx = netfs_inode(inode);
 	struct writeback_control wbc = {
 		.sync_mode	= WB_SYNC_NONE,
 		.for_sync	= true,
 		.nr_to_write	= LONG_MAX,
 		.range_start	= iocb->ki_pos,
 		.range_end	= iocb->ki_pos + iter->count,
 	};
 	struct netfs_io_request *wreq = NULL;
 	struct netfs_folio *finfo;
 	struct folio *folio;
 	enum netfs_how_to_modify howto;
 	enum netfs_folio_trace trace;
 	unsigned int bdp_flags = (iocb->ki_flags & IOCB_SYNC) ? 0: BDP_ASYNC;
 	ssize_t written = 0, ret;
 	loff_t i_size, pos = iocb->ki_pos, from, to;
 	size_t max_chunk = PAGE_SIZE << MAX_PAGECACHE_ORDER;
 	bool maybe_trouble = false;

 	if (unlikely(test_bit(NETFS_ICTX_WRITETHROUGH, &ctx->flags) ||
 		     iocb->ki_flags & (IOCB_DSYNC | IOCB_SYNC))
 	    ) {
 		if (pos < i_size_read(inode)) {
 			ret = filemap_write_and_wait_range(mapping, pos, pos + iter->count);
 			if (ret < 0) {
 				goto out;
 			}
 		}

 		wbc_attach_fdatawrite_inode(&wbc, mapping->host);

 		wreq = netfs_begin_writethrough(iocb, iter->count);
 		if (IS_ERR(wreq)) {
 			wbc_detach_inode(&wbc);
 			ret = PTR_ERR(wreq);
 			wreq = NULL;
 			goto out;
 		}
 		if (!is_sync_kiocb(iocb))
 			wreq->iocb = iocb;
 		wreq->cleanup = netfs_cleanup_buffered_write;
 	}

 	do {
 		size_t flen;
 		size_t offset;	/* Offset into pagecache folio */
 		size_t part;	/* Bytes to write to folio */
 		size_t copied;	/* Bytes copied from user */

 		ret = balance_dirty_pages_ratelimited_flags(mapping, bdp_flags);
 		if (unlikely(ret < 0))
 			break;

 		offset = pos & (max_chunk - 1);
 		part = min(max_chunk - offset, iov_iter_count(iter));

 		/* Bring in the user pages that we will copy from _first_ lest
 		 * we hit a nasty deadlock on copying from the same page as
 		 * we're writing to, without it being marked uptodate.
 		 *
 		 * Not only is this an optimisation, but it is also required to
 		 * check that the address is actually valid, when atomic
 		 * usercopies are used below.
 		 *
 		 * We rely on the page being held onto long enough by the LRU
 		 * that we can grab it below if this causes it to be read.
 		 */
 		ret = -EFAULT;
 		if (unlikely(fault_in_iov_iter_readable(iter, part) == part))
 			break;

-		ret = -ENOMEM;
 		folio = netfs_grab_folio_for_write(mapping, pos, part);
-		if (!folio)
+		if (IS_ERR(folio)) {
+			ret = PTR_ERR(folio);
 			break;
+		}

 		flen = folio_size(folio);
 		offset = pos & (flen - 1);
 		part = min_t(size_t, flen - offset, part);

 		if (signal_pending(current)) {
 			ret = written ? -EINTR : -ERESTARTSYS;
 			goto error_folio_unlock;
 		}

 		/* See if we need to prefetch the area we're going to modify.
 		 * We need to do this before we get a lock on the folio in case
 		 * there's more than one writer competing for the same cache
 		 * block.
 		 */
 		howto = netfs_how_to_modify(ctx, file, folio, netfs_group,
 					    flen, offset, part, maybe_trouble);
 		_debug("howto %u", howto);
 		switch (howto) {
 		case NETFS_JUST_PREFETCH:
 			ret = netfs_prefetch_for_write(file, folio, offset, part);
 			if (ret < 0) {
 				_debug("prefetch = %zd", ret);
 				goto error_folio_unlock;
 			}
 			break;
 		case NETFS_FOLIO_IS_UPTODATE:
 		case NETFS_WHOLE_FOLIO_MODIFY:
 		case NETFS_STREAMING_WRITE_CONT:
 			break;
 		case NETFS_MODIFY_AND_CLEAR:
 			zero_user_segment(&folio->page, 0, offset);
 			break;
 		case NETFS_STREAMING_WRITE:
 			ret = -EIO;
 			if (WARN_ON(folio_get_private(folio)))
 				goto error_folio_unlock;
 			break;
 		case NETFS_FLUSH_CONTENT:
 			trace_netfs_folio(folio, netfs_flush_content);
 			from = folio_pos(folio);
 			to = from + folio_size(folio) - 1;
 			folio_unlock(folio);
 			folio_put(folio);
 			ret = filemap_write_and_wait_range(mapping, from, to);
 			if (ret < 0)
 				goto error_folio_unlock;
 			continue;
 		}

 		if (mapping_writably_mapped(mapping))
 			flush_dcache_folio(folio);

 		copied = copy_folio_from_iter_atomic(folio, offset, part, iter);

 		flush_dcache_folio(folio);

 		/* Deal with a (partially) failed copy */
 		if (copied == 0) {
 			ret = -EFAULT;
 			goto error_folio_unlock;
 		}

 		trace = (enum netfs_folio_trace)howto;
 		switch (howto) {
 		case NETFS_FOLIO_IS_UPTODATE:
 		case NETFS_JUST_PREFETCH:
 			netfs_set_group(folio, netfs_group);
 			break;
 		case NETFS_MODIFY_AND_CLEAR:
 			zero_user_segment(&folio->page, offset + copied, flen);
 			netfs_set_group(folio, netfs_group);
 			folio_mark_uptodate(folio);
 			break;
 		case NETFS_WHOLE_FOLIO_MODIFY:
 			if (unlikely(copied < part)) {
 				maybe_trouble = true;
 				iov_iter_revert(iter, copied);
 				copied = 0;
 				goto retry;
 			}
 			netfs_set_group(folio, netfs_group);
 			folio_mark_uptodate(folio);
 			break;
 		case NETFS_STREAMING_WRITE:
 			if (offset == 0 && copied == flen) {
 				netfs_set_group(folio, netfs_group);
 				folio_mark_uptodate(folio);
 				trace = netfs_streaming_filled_page;
 				break;
 			}
 			finfo = kzalloc(sizeof(*finfo), GFP_KERNEL);
 			if (!finfo) {
 				iov_iter_revert(iter, copied);
 				ret = -ENOMEM;
 				goto error_folio_unlock;
 			}
 			finfo->netfs_group = netfs_get_group(netfs_group);
 			finfo->dirty_offset = offset;
 			finfo->dirty_len = copied;
 			folio_attach_private(folio, (void *)((unsigned long)finfo |
 							     NETFS_FOLIO_INFO));
 			break;
 		case NETFS_STREAMING_WRITE_CONT:
 			finfo = netfs_folio_info(folio);
 			finfo->dirty_len += copied;
 			if (finfo->dirty_offset == 0 && finfo->dirty_len == flen) {
 				if (finfo->netfs_group)
 					folio_change_private(folio, finfo->netfs_group);
 				else
 					folio_detach_private(folio);
 				folio_mark_uptodate(folio);
 				kfree(finfo);
 				trace = netfs_streaming_cont_filled_page;
 			}
 			break;
 		default:
 			WARN(true, "Unexpected modify type %u ix=%lx\n",
 			     howto, folio->index);
 			ret = -EIO;
 			goto error_folio_unlock;
 		}

 		trace_netfs_folio(folio, trace);

 		/* Update the inode size if we moved the EOF marker */
 		i_size = i_size_read(inode);
 		pos += copied;
 		if (pos > i_size) {
 			if (ctx->ops->update_i_size) {
 				ctx->ops->update_i_size(inode, pos);
 			} else {
 				i_size_write(inode, pos);
 #if IS_ENABLED(CONFIG_FSCACHE)
 				fscache_update_cookie(ctx->cache, NULL, &pos);
 #endif
 			}
 		}
 		written += copied;

 		if (likely(!wreq)) {
 			folio_mark_dirty(folio);
 		} else {
 			if (folio_test_dirty(folio))
 				/* Sigh.  mmap. */
 				folio_clear_dirty_for_io(folio);
 			/* We make multiple writes to the folio... */
 			if (!folio_test_writeback(folio)) {
 				folio_wait_fscache(folio);
 				folio_start_writeback(folio);
 				folio_start_fscache(folio);
 				if (wreq->iter.count == 0)
 					trace_netfs_folio(folio, netfs_folio_trace_wthru);
 				else
 					trace_netfs_folio(folio, netfs_folio_trace_wthru_plus);
 			}
 			netfs_advance_writethrough(wreq, copied,
 						   offset + copied == flen);
 		}
 	retry:
 		folio_unlock(folio);
 		folio_put(folio);
 		folio = NULL;

 		cond_resched();
 	} while (iov_iter_count(iter));

 out:
 	if (unlikely(wreq)) {
 		ret = netfs_end_writethrough(wreq, iocb);
 		wbc_detach_inode(&wbc);
 		if (ret == -EIOCBQUEUED)
 			return ret;
 	}

 	iocb->ki_pos += written;
 	_leave(" = %zd [%zd]", written, ret);
 	return written ? written : ret;

 error_folio_unlock:
 	folio_unlock(folio);
 	folio_put(folio);
 	goto out;
 }
 EXPORT_SYMBOL(netfs_perform_write);


